CONTACT_SECTION = '<section class="contact-section" id="contact" aria-labelledby="contact-title"><div class="wrap contact-grid"><div class="contact-copy"><div class="eyebrow">LET’S TALK LAND</div><h2 id="contact-title">Tell us what you have in mind.</h2><p>Have a property in mind, need a particular acreage, or want to see the land? Share your plans with Danlo and start the conversation.</p><div class="contact-methods"><div class="contact-method"><small>CALL DANLO</small><a href="tel:+254726892581">+254 726 892 581</a><a href="tel:+254707117466">+254 707 117 466</a></div><div class="contact-method"><small>EMAIL</small><a href="mailto:danlopropertiesltd@gmail.com">danlopropertiesltd@gmail.com</a></div><div class="contact-method"><small>BASED IN</small><span>Kitengela, Kajiado, Kenya</span></div></div></div><div class="inquiry-card"><h3 id="inquiry-heading">Your land inquiry</h3><p class="form-help">We’ll prepare an email with your details for you to review and send. Fields marked * are required.</p><form id="land-inquiry"><div class="inquiry-fields"><div class="inquiry-field"><label for="inquiry-name">Full name *</label><input id="inquiry-name" name="name" autocomplete="name" maxlength="100" required></div><div class="inquiry-field"><label for="inquiry-email">Email address *</label><input id="inquiry-email" name="email" type="email" autocomplete="email" maxlength="180" required></div><div class="inquiry-field"><label for="inquiry-phone">Phone <span>(optional)</span></label><input id="inquiry-phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div><div class="inquiry-field"><label for="inquiry-type">How can we help? *</label><select id="inquiry-type" name="type" required><option value="requirements">Land requirements</option><option value="property">Property inquiry</option><option value="visit">Arrange a site visit</option><option value="contact">General inquiry</option></select></div><div class="inquiry-field full"><label for="inquiry-property">Property <span>(optional)</span></label><select id="inquiry-property" name="property"><option value="">No specific property yet</option></select></div><div class="inquiry-field visit-field" hidden><label for="visit-date">Preferred visit date *</label><input id="visit-date" name="visitDate" type="date" disabled></div><div class="inquiry-field visit-field" hidden><label for="visit-time">Preferred time *</label><select id="visit-time" name="visitTime" disabled><option value="">Select a time</option><option>Morning (9 am–12 pm)</option><option>Afternoon (12 pm–4 pm)</option><option>Flexible</option></select></div><p class="form-help visit-field" style="grid-column:1/-1;margin:0" hidden>Times are in Kenya time. Danlo will confirm availability and the meeting point with you.</p><div class="inquiry-field full"><label for="inquiry-message">Tell us about your plans *</label><textarea id="inquiry-message" name="message" maxlength="2500" placeholder="Preferred location, acreage, intended use, and budget. Tell us any access needs or questions about the land." required></textarea></div></div><button class="btn inquiry-submit" type="submit">Prepare Email Inquiry<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" aria-hidden="true"><path d="M4 10h12m-5-5 5 5-5 5"/></svg></button></form><div class="inquiry-review" id="inquiry-review" hidden><h4>Review your inquiry.</h4><p>Open your email app to send this to Danlo, or copy the inquiry into an email to danlopropertiesltd@gmail.com.</p><div class="inquiry-preview" id="inquiry-preview"></div><div class="inquiry-review-actions"><a class="btn" id="inquiry-email-link" href="mailto:danlopropertiesltd@gmail.com">Open Email App</a><button class="btn secondary inquiry-copy-button" type="button" id="copy-inquiry">Copy Inquiry</button></div><p class="inquiry-feedback" id="inquiry-feedback" role="status" aria-live="polite"></p></div></div></div></section>'
INQUIRY_JS = '\n(()=>{\nconst form=document.getElementById(\'land-inquiry\');\nwindow.startDanloInquiry=(type,property)=>{if(!form){const visitLink=document.querySelector(\'.property-actions a[href*="inquiry=visit"]\');if(!property&&visitLink)property=new URL(visitLink.href).searchParams.get(\'property\');location.href=\'index.html?inquiry=\'+encodeURIComponent(type||\'contact\')+(property?\'&property=\'+encodeURIComponent(property):\'\')+\'#contact\';return}const dialog=document.getElementById(\'panel\');if(dialog.open)dialog.close();document.getElementById(\'inquiry-type\').value=[\'requirements\',\'property\',\'visit\',\'contact\'].includes(type)?type:\'contact\';if(property)document.getElementById(\'inquiry-property\').value=property;syncVisitFields();document.getElementById(\'inquiry-review\').hidden=true;document.getElementById(\'inquiry-feedback\').textContent=\'\';document.getElementById(\'contact\').scrollIntoView({behavior:matchMedia(\'(prefers-reduced-motion: reduce)\').matches?\'auto\':\'smooth\'});};\nif(!form)return;\nconst propertySelect=document.getElementById(\'inquiry-property\');landInventory.forEach(p=>{const option=document.createElement(\'option\');option.value=p.id;option.textContent=p.acres+\' acres — \'+p.title;propertySelect.append(option)});\nconst params=new URLSearchParams(location.search);if(params.has(\'inquiry\')){document.getElementById(\'inquiry-type\').value=[\'requirements\',\'property\',\'visit\',\'contact\'].includes(params.get(\'inquiry\'))?params.get(\'inquiry\'):\'contact\';}if(landInventory.some(p=>p.id===params.get(\'property\')))propertySelect.value=params.get(\'property\');\nconst typeSelect=document.getElementById(\'inquiry-type\'),dateInput=document.getElementById(\'visit-date\'),timeSelect=document.getElementById(\'visit-time\');\nconst today=new Intl.DateTimeFormat(\'en-CA\',{timeZone:\'Africa/Nairobi\',year:\'numeric\',month:\'2-digit\',day:\'2-digit\'}).format(new Date());dateInput.min=today;\nfunction syncVisitFields(){const visiting=document.getElementById(\'inquiry-type\').value===\'visit\';document.querySelectorAll(\'.visit-field\').forEach(el=>el.hidden=!visiting);for(const field of [document.getElementById(\'visit-date\'),document.getElementById(\'visit-time\')]){field.disabled=!visiting;field.required=visiting;}document.getElementById(\'inquiry-heading\').textContent=visiting?\'Arrange your site visit\':\'Your land inquiry\';form.querySelector(\'[type="submit"]\').firstChild.textContent=visiting?\'Prepare Site Visit Request\':\'Prepare Email Inquiry\';}\ntypeSelect.addEventListener(\'change\',syncVisitFields);syncVisitFields();\nlet prepared=\'\';\nconst review=document.getElementById(\'inquiry-review\'),feedback=document.getElementById(\'inquiry-feedback\');\ndateInput.addEventListener(\'input\',()=>dateInput.setCustomValidity(\'\'));\nform.addEventListener(\'input\',()=>{review.hidden=true;feedback.textContent=\'\'});\nform.addEventListener(\'change\',()=>{review.hidden=true;feedback.textContent=\'\'});\nform.addEventListener(\'submit\',event=>{event.preventDefault();if(!form.reportValidity())return;const values=new FormData(form);if(values.get(\'type\')===\'visit\'&&values.get(\'visitDate\')<today){dateInput.setCustomValidity(\'Choose today or a future date.\');dateInput.reportValidity();return;}const types={requirements:\'Land requirements\',property:\'Property inquiry\',visit:\'Site visit request\',contact:\'General inquiry\'};const selected=landInventory.find(p=>p.id===values.get(\'property\'));const subject=\'Danlo Properties — \'+types[values.get(\'type\')]+(selected?\': \'+selected.acres+\' acres, \'+selected.title:\'\');const body=[\'Hello Danlo Properties,\',\'\',types[values.get(\'type\')],selected?\'Property: \'+selected.acres+\' acres — \'+selected.title+\' (\'+selected.area+\')\':\'Property: No specific property selected\',selected?\'Listing: \'+new URL(selected.url||selected.slug||\'\',location.href).href:null,values.get(\'type\')===\'visit\'?\'Preferred date: \'+values.get(\'visitDate\'):null,values.get(\'type\')===\'visit\'?\'Preferred time: \'+values.get(\'visitTime\')+\' (Kenya time)\':null,values.get(\'type\')===\'visit\'?\'Please confirm availability and the meeting point.\':null,\'\',String(values.get(\'message\')).trim(),\'\',\'Name: \'+String(values.get(\'name\')).trim(),\'Email: \'+String(values.get(\'email\')).trim(),values.get(\'phone\')?\'Phone: \'+String(values.get(\'phone\')).trim():\'\'].filter(line=>line!==null).join(\'\\n\');prepared=\'To: danlopropertiesltd@gmail.com\\nSubject: \'+subject+\'\\n\\n\'+body;document.getElementById(\'inquiry-preview\').textContent=prepared;document.getElementById(\'inquiry-email-link\').href=\'mailto:danlopropertiesltd@gmail.com?subject=\'+encodeURIComponent(subject)+\'&body=\'+encodeURIComponent(body);review.hidden=false;feedback.textContent=\'Your email is ready to review. It has not been sent.\';review.scrollIntoView({behavior:matchMedia(\'(prefers-reduced-motion: reduce)\').matches?\'auto\':\'smooth\',block:\'nearest\'});});\ndocument.getElementById(\'copy-inquiry\').addEventListener(\'click\',async()=>{try{await navigator.clipboard.writeText(prepared);feedback.textContent=\'Inquiry copied. Paste it into an email and send it to Danlo.\'}catch{feedback.textContent=\'Select and copy the inquiry text above, then paste it into your email.\'}});\n})();\n'
